	protected CreateDSPCommand generateNewCommand() {
        CreateDSPCommand command = new CreateDSPCommand( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16) );
		
		return( command );
	}

		/**
		 * Returns a new populated DSP
		 * 
		 * @return UpdateDSPCommand alias
		 */
	protected UpdateDSPCommand generateUpdateCommand() {
	        UpdateDSPCommand command = new UpdateDSPCommand( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  new HashSet<>() );
			
			return( command );
		}
